for(const instrument of data.catalogue)if(!names[instrument.symbol])names[instrument.symbol]=instrument.name||instrument.symbol;
function instrumentPrice(symbol,value){const item=data.catalogue.find(i=>i.symbol===symbol);return Number.isFinite(value)?new Intl.NumberFormat(undefined,{style:'currency',currency:market()[symbol]?.currency||item?.listing_currency||'USD'}).format(value):'Not included';}
function plan(){return data.plans[state.index];}
function pct(v,digits=1){return Number.isFinite(v)?new Intl.NumberFormat(undefined,{style:'percent',maximumFractionDigits:digits}).format(v):'Unavailable';}
function cash(v,compact=false){if(!Number.isFinite(v))return 'Unavailable';return new Intl.NumberFormat(undefined,{style:'currency',currency:plan().mandate.base_currency,maximumFractionDigits:compact?1:0,notation:compact?'compact':'standard'}).format(v);}
function text(id,value){$(id).textContent=value;}
function el(tag,value,className){const node=document.createElement(tag);if(value!==undefined)node.textContent=value;if(className)node.className=className;return node;}
function human(value){return String(value??'Unavailable').toLowerCase().replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}
function weights(){return plan().allocation.weights||{};}
function bucket(item){return item.symbol==='TIP'?'inflation':item.bucket;}
function held(){return data.catalogue.filter(i=>(weights()[i.symbol]||0)>1e-8);}
function market(){return data.latest_market?.instruments||data.market[plan().price_session]?.instruments||{};}
function view(name){window.scrollTo(0,0);renderPortfolioIdentity(name);const referenceView=['growth','news','engines','dynamic','observations'].includes(name);document.querySelector('.controls').hidden=referenceView;document.querySelector('[aria-label="Plan data status"]').hidden=referenceView;$('download-plan').hidden=referenceView;$('download-pdf').hidden=referenceView||!data.pdf_links?.[plan().id];document.querySelector('.kpi-grid').hidden=!['overview','scenarios'].includes(name);document.querySelectorAll('[data-panel]').forEach(n=>n.hidden=n.dataset.panel!==name);document.querySelectorAll('[data-view]').forEach(n=>{n.classList.toggle('active',n.dataset.view===name);if(n.dataset.view===name)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});if($('section-jump'))$('section-jump').value=name;text('page-title',titles[name]);text('announcement',titles[name]);if(name==='portfolio'&&state.asset)assetDetail(state.asset);}
function pair(parent,label,value){const row=el('div');row.append(el('span',label),el('strong',value));parent.append(row);}
function insight(title,description,index){const row=el('div',undefined,'insight');const copy=el('div');copy.append(el('strong',title),el('p',description));row.append(el('span',String(index).padStart(2,'0'),'insight-number'),copy);$('insights').append(row);}
function render(){const p=plan(),m=p.mandate,s=p.simulations,a=p.allocation,summary=s?.summary.proposed;
 text('currency',m.base_currency);text('snapshot-date',p.price_session);text('horizon-label',`${m.horizon_years}-year planning horizon`);
 text('profile-note',m.target_total_return!=null?'Archived investor illustration; former targets are superseded by the Growth & Resilience policy.':'A separate illustrative client profile, not a suitability recommendation.');
 text('source-title',p.historical_preview?'Historical planning preview · not live market data':'Saved planning snapshot · not a live account');
 text('source-description',`Price session ${p.price_session}. ${human(p.qualification.status)}. ${p.qualification.public_recommendations_enabled?'Saved release status requires operator verification.':'Public recommendations remain disabled.'}`);
 text('value-label',`Scenario median value · ${s?.years??m.horizon_years} years`);
 text('median-value',summary?cash(state.capital*(1+summary.median_total_return)):'Unavailable');text('median-return',summary?`${pct(summary.median_total_return)} total return`:'No saved simulation');
 text('downside-value',summary?cash(state.capital*(1+summary.p05_total_return)):'Unavailable');text('downside-return',summary?`${pct(summary.p05_total_return)} over ${s.years} years`:'No saved simulation');
 text('drawdown-value',summary?pct(summary.p95_drawdown_magnitude):'Unavailable');text('risk-preference',`Archived illustration · full ${m.horizon_years}-year horizon`);
 text('holdings-value',`${held().length} held · ${data.core_symbols?.length||0} research eligible`);text('cash-value',`${pct(weights().USD_CASH||0)} uninvested cash`);text('donut-count',held().length);
 $('empty-state').hidden=Boolean(a.weights);text('empty-reason',`${human(a.status)}. This saved plan has no allocation; review its constraints before any recommendation.`);
 text('projection-subtitle',`Conditional wealth paths over ${s?.years??m.horizon_years} years, after modeled costs.`);text('path-count',s?`${s.paths.toLocaleString()} simulated paths`:'No simulation');
 const windows=$('chart-windows');windows.replaceChildren();if(s){const years=[...new Set([1,3,5,s.years].filter(y=>y<=s.years))].sort((a,b)=>a-b);years.forEach(y=>{const b=el('button',`${y}Y`);b.classList.toggle('active',y===state.window);b.setAttribute('aria-pressed',String(y===state.window));b.addEventListener('click',()=>{state.window=y;state.hover=0;$('fan-tooltip').hidden=true;text('chart-readout','');render();});windows.append(b);});}
 text('chart-caption',s?`Showing ${state.window} of ${s.years} modeled years. Cards always use the full ${s.years}-year horizon. The band is pointwise uncertainty, not a loss boundary. Amount changes scale the saved paths; they do not rerun suitability, taxes, fees or allocation.`:'No saved scenario distribution is available for this allocation.');
 drawFan();drawDonut();renderAssets();renderScenarios();renderRisk();renderFacts();renderIntelligence();renderTraining();renderAllocationLab();
 $('insights').replaceChildren();insight('Diversification needs a risk lens',`${held().length} instruments across ${Object.keys(groupWeights()).length} capital groups. Correlations can rise during market stress.`,1);
 if(summary)insight('Look beyond the median',`The modeled frequency of an ending loss is ${pct(summary.terminal_loss_frequency)}. The 95th-percentile drawdown is ${pct(summary.p95_drawdown_magnitude)} across ${s.years} years. These are conditional estimates.`,2);
 insight(m.target_total_return!=null?'Keep the original goal visible':'Match the plan to the investor',m.target_total_return!=null?`The ${pct(m.target_total_return)} total-return target and ${pct(m.drawdown_preference)} loss preference are aspirations, not promised outcomes. See risk & readiness for suitability limits.`:'Profile changes show separate saved examples. A different risk profile requires a fresh suitability assessment.',3);
 text('market-context',Object.keys(market()).length?`Adjusted closing observations as of ${data.latest_market?.session||p.price_session}; not live or executable quotes. Each quote retains its displayed listing or valuation currency; illustration currency is separate.`:'No price history was included in this saved viewer. No live prices are being requested.');
 $('market-watch').replaceChildren();(held().length?held().slice(0,4):data.catalogue.slice(0,4)).forEach(i=>{const row=el('div',undefined,'watch-row'),button=el('button',i.symbol,'text-button');button.addEventListener('click',()=>{view('portfolio');assetDetail(i.symbol);});row.append(button,el('span',names[i.symbol]),el('strong',Number.isFinite(market()[i.symbol]?.close)?instrumentPrice(i.symbol,market()[i.symbol].close):'Not included'));$('market-watch').append(row);});
 if(state.asset)assetDetail(state.asset);
}
function groupWeights(){const result={};data.catalogue.forEach(i=>{const w=weights()[i.symbol]||0;if(w>1e-8)result[bucket(i)]=(result[bucket(i)]||0)+w;});if(weights().USD_CASH>1e-8)result.cash=weights().USD_CASH;return result;}
function drawDonut(){const c=$('allocation-donut'),ctx=c.getContext('2d'),parts=Object.entries(groupWeights());ctx.clearRect(0,0,c.width,c.height);let start=-Math.PI/2;const total=parts.reduce((sum,p)=>sum+p[1],0);$('allocation-legend').replaceChildren();if(!total){ctx.strokeStyle='#e7ece8';ctx.lineWidth=32;ctx.beginPath();ctx.arc(170,140,95,0,Math.PI*2);ctx.stroke();return;}parts.forEach(([key,w],i)=>{const end=start+w/total*Math.PI*2;ctx.strokeStyle=palette[i];ctx.lineWidth=32;ctx.beginPath();ctx.arc(170,140,95,start+.012,end-.012);ctx.stroke();start=end;const row=el('div'),label=el('span'),dot=el('i');dot.style.backgroundColor=palette[i];label.append(dot,document.createTextNode(groups[key]));row.append(label,el('strong',pct(w)));$('allocation-legend').append(row);});c.setAttribute('aria-label',parts.map(([g,w])=>`${groups[g]} ${pct(w)}`).join(', '));}
let chartGeometry=null;
function drawFan(){const c=$('fan'),ctx=c.getContext('2d'),s=plan().simulations,W=c.width,H=c.height,L=85,R=30,T=25,B=45;ctx.clearRect(0,0,W,H);chartGeometry=null;if(!s){ctx.fillStyle='#647780';ctx.font='16px sans-serif';ctx.fillText('No saved simulation available',L,H/2);return;}
 const end=Math.min(state.window*252,s.fan.proposed[0].length),series=s.fan.proposed.map(a=>[1,...a.slice(0,end)]),ref=[1,...s.fan.strategic_reference[1].slice(0,end)],show=$('show-reference').checked;
 let lo=1,hi=1;series.forEach(line=>line.forEach(v=>{lo=Math.min(lo,v);hi=Math.max(hi,v);}));if(show)ref.forEach(v=>{lo=Math.min(lo,v);hi=Math.max(hi,v);});const goal=plan().mandate.target_total_return;const goalEnd=goal!=null?Math.pow(1+goal,state.window/s.years):null;if(goalEnd!=null)hi=Math.max(hi,goalEnd);const span=Math.max(hi-lo,.1);lo=Math.max(0,lo-span*.1);hi+=span*.1;
 const x=i=>L+i/end*(W-L-R),y=v=>H-B-(v-lo)/(hi-lo)*(H-T-B);ctx.font='12px sans-serif';ctx.lineWidth=1;
 for(let j=0;j<5;j++){const v=lo+(hi-lo)*j/4,Y=y(v);ctx.strokeStyle='#e7ece8';ctx.beginPath();ctx.moveTo(L,Y);ctx.lineTo(W-R,Y);ctx.stroke();ctx.fillStyle='#647780';ctx.fillText(cash(v*state.capital,true),2,Y+4);}
 for(let j=0;j<=4;j++){ctx.fillStyle='#647780';ctx.fillText(`${(state.window*j/4).toFixed(state.window<4?1:0)}y`,x(end*j/4)-8,H-14);}
 ctx.fillStyle='#dfede5';ctx.beginPath();series[0].forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));for(let i=end;i>=0;i--)ctx.lineTo(x(i),y(series[2][i]));ctx.closePath();ctx.fill();
 const line=(points,color,dash=[])=>{ctx.strokeStyle=color;ctx.lineWidth=2.6;ctx.setLineDash(dash);ctx.beginPath();points.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.stroke();ctx.setLineDash([]);};line(series[1],'#177b68');if(show)line(ref,'#be964b');
 if(goalEnd!=null){line(Array.from({length:end+1},(_,i)=>Math.pow(1+goal,i/(252*s.years))),'#8a809b',[5,5]);ctx.fillStyle='#716a7b';ctx.fillText('Target trajectory · not a forecast',L+10,T+10);}
 chartGeometry={x,y,end,series,ref,L,R,W};
 if(state.hover>0&&state.hover<=end){const i=state.hover;ctx.strokeStyle='#b6c5bc';ctx.lineWidth=1;ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(x(i),T);ctx.lineTo(x(i),H-B);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#177b68';ctx.beginPath();ctx.arc(x(i),y(series[1][i]),4,0,Math.PI*2);ctx.fill();}
}
function inspect(index){if(!chartGeometry)return;state.hover=Math.max(0,Math.min(chartGeometry.end,index));drawFan();const g=chartGeometry,i=state.hover;const value=`Year ${(i/252).toFixed(2)} · Median ${cash(g.series[1][i]*state.capital)} · P05 ${cash(g.series[0][i]*state.capital)} · P95 ${cash(g.series[2][i]*state.capital)}`;text('fan-tooltip',value);$('fan-tooltip').hidden=false;text('chart-readout',value);}
function renderAssets(){const query=$('asset-search').value.trim().toLowerCase(),only=$('held-only').checked;const list=data.catalogue.filter(i=>(!$('core-only').checked||(data.core_symbols||[]).includes(i.symbol))&&(!only||(weights()[i.symbol]||0)>1e-8)&&`${i.symbol} ${names[i.symbol]} ${groups[bucket(i)]} ${i.region||""} ${i.venue||""} ${i.listing_currency||""} ${i.asset_type||""}`.toLowerCase().includes(query));list.sort((a,b)=>{const comparison=state.sort==='weight'?(weights()[a.symbol]||0)-(weights()[b.symbol]||0):a.symbol.localeCompare(b.symbol);return (state.descending?-1:1)*comparison;});$('asset-rows').replaceChildren();list.forEach(i=>{const w=weights()[i.symbol]||0,row=el('tr'),symbol=el('td'),button=el('button',i.symbol,'text-button');button.setAttribute('aria-label',`View ${i.symbol} historical detail`);button.addEventListener('click',()=>assetDetail(i.symbol));symbol.append(button,el('div',`${names[i.symbol]} · ${i.asset_type||'instrument'} · ${i.region||'region unavailable'} · ${i.listing_currency||'currency unavailable'}`,'small muted'));const weight=el('td',pct(w,2)),bar=el('span',undefined,'weight-bar');bar.style.width=`${Math.min(80,w*160)}px`;weight.append(bar);const price=market()[i.symbol]?.close;row.append(symbol,el('td',groups[bucket(i)]),weight,el('td',pct(plan().allocation.variance_contributions?.[i.symbol],2)),el('td',cash(w*state.capital)),el('td',Number.isFinite(price)?instrumentPrice(i.symbol,price):'Not included'),el('td',i.benchmark_only?'Benchmark only':w>1e-8?'In saved allocation':!i.research_enabled?'Additional data/FX qualification required':plan().excluded_instruments[i.symbol]?human(plan().excluded_instruments[i.symbol]):'Not allocated'),el('td',data.allocation_lab?.roles?.[i.symbol]||names[i.symbol]));$('asset-rows').append(row);});if(!list.length){const row=el('tr'),cell=el('td','No instruments match this search.');cell.colSpan=8;row.append(cell);$('asset-rows').append(row);}text('asset-count',`${list.length} of ${data.catalogue.length} instruments`);}
function assetDetail(symbol){state.asset=symbol;$('asset-detail').hidden=false;text('asset-title',`${symbol} · ${names[symbol]||symbol}`);text('asset-description',`${pct(weights()[symbol]||0,2)} of saved capital allocation. Historical adjusted closing prices in ${market()[symbol]?.currency||data.catalogue.find(i=>i.symbol===symbol)?.listing_currency||'USD'}.`);const points=market()[symbol]?.history||[],c=$('asset-chart'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.font='13px sans-serif';ctx.fillStyle='#647780';if(points.length<2){ctx.fillText('No usable historical series included for this instrument.',60,140);text('asset-history-note','No prices have been manufactured or forward-filled.');return;}let lo=Infinity,hi=-Infinity;points.forEach(p=>{lo=Math.min(lo,p[1]);hi=Math.max(hi,p[1]);});const span=Math.max(hi-lo,.01),first=Date.parse(points[0][0]),last=Date.parse(points.at(-1)[0]);const x=d=>70+(Date.parse(d)-first)/(last-first)*(c.width-100),y=v=>c.height-40-(v-lo+span*.1)/(span*1.2)*(c.height-65);for(let j=0;j<4;j++){const v=lo+span*j/3,Y=y(v);ctx.strokeStyle='#e7ece8';ctx.beginPath();ctx.moveTo(70,Y);ctx.lineTo(c.width-30,Y);ctx.stroke();ctx.fillText(instrumentPrice(symbol,v),2,Y+4);}ctx.strokeStyle='#177b68';ctx.lineWidth=2.4;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(x(p[0]),y(p[1])):ctx.moveTo(x(p[0]),y(p[1])));ctx.stroke();ctx.fillText(points[0][0],70,c.height-10);ctx.fillText(points.at(-1)[0],c.width-110,c.height-10);text('asset-history-note',`${points.length} actual observations · ${points[0][0]} to ${points.at(-1)[0]} · Gaps are not filled; this is not a total-return performance backtest or a live quote.`);}
function renderScenarios(){const s=plan().simulations;$('scenario-rows').replaceChildren();text('scenario-context',s?`Full ${s.years}-year horizon · ${s.paths.toLocaleString()} paths · conditional on the saved model and inputs.`:'No saved simulation available.');const metrics=[['Median total return','median_total_return'],['5th-percentile total return','p05_total_return'],['95th-percentile total return','p95_total_return'],['Ending loss frequency','terminal_loss_frequency'],['95th-percentile maximum drawdown','p95_drawdown_magnitude'],['Archived 50% / 5% diagnostic (superseded target)','joint_50pct_return_5pct_drawdown_frequency']];metrics.forEach(([label,key])=>{const row=el('tr');row.append(el('td',label),el('td',pct(s?.summary.proposed[key])),el('td',pct(s?.summary.strategic_reference[key])));$('scenario-rows').append(row);});$('profile-rows').replaceChildren();data.plans.forEach((p,index)=>{const row=el('tr'),cell=el('td'),button=el('button',p.title,'text-button');button.addEventListener('click',()=>selectPlan(index));cell.append(button);row.append(cell,el('td',`${p.mandate.horizon_years} years`),el('td',pct(p.simulations?.summary.proposed.median_total_return)),el('td',pct(p.simulations?.summary.proposed.p95_drawdown_magnitude)),el('td',pct(p.mandate.drawdown_preference)));$('profile-rows').append(row);});}
const reasonLabels={HISTORICAL_OPERATOR_PREVIEW:'This plan uses a historical snapshot and is available for operator review only.',CASH_YIELD_UNVERIFIED:'Future cash yield has not been verified. The saved assumption may be zero.',TRADING_COST_INPUTS_ILLUSTRATIVE:'Trading-cost inputs are illustrative and require validation.',FUND_EXPENSE_INPUTS_UNVERIFIED:'Fund expense assumptions require verification before release.'};
function renderRisk(){const p=plan(),a=p.allocation;$('risk-metrics').replaceChildren();const metrics=[['Archived loss preference (not active policy)',pct(p.mandate.drawdown_preference)],['Financial loss capacity',pct(p.mandate.financial_loss_capacity)],['Planning annual volatility',pct(a.planning_annual_volatility)],['Historical daily expected shortfall · 95%',pct(a.historical_daily_es95)],['Estimated rebalance cost',pct(a.estimated_rebalance_cost_fraction,3)],['Uninvested cash floor',pct(a.cash_floor)],['Risk exposure multiplier',Number.isFinite(p.risk.exposure_multiplier)?`${p.risk.exposure_multiplier.toFixed(2)}×`:'Unavailable'],['Risk review required',p.risk.review_required?'Yes':'No saved review flag']];metrics.forEach(([k,v])=>pair($('risk-metrics'),k,v));Object.entries(a.hypothetical_stress_losses_including_costs||{}).forEach(([k,v])=>pair($('risk-metrics'),`Hypothetical stress · ${['Growth shock','Inflation shock','Liquidity shock'][Number(k)]||human(k)}`,pct(v)));
 $('readiness').replaceChildren();Object.entries(p.qualification.checks||{}).forEach(([k,v])=>pair($('readiness'),human(k),human(v)));pair($('readiness'),'Saved release status',human(p.qualification.status));pair($('readiness'),'Public recommendations',p.qualification.public_recommendations_enabled?'Saved flag enabled; review required':'Disabled');
 $('risk-reasons').replaceChildren();[...new Set([...(p.qualification.client_reasons||[]),...p.hard_blocks])].forEach(r=>$('risk-reasons').append(el('div',reasonLabels[r]||human(r),'reason')));if(!$('risk-reasons').children.length)$('risk-reasons').append(el('p','No saved blocking reasons. This viewer does not grant release approval.'));}
function renderFacts(){const p=plan(),s=p.simulations;$('plan-facts').replaceChildren();[['Profile',p.title],['Planning horizon',`${p.mandate.horizon_years} years`],['Illustration currency',p.mandate.base_currency],['Original account value',cash(p.mandate.account_value)],['Price session',p.price_session],['Decision timestamp',p.as_of],['Allocation status',human(p.allocation.status)],['Archived plan macro alpha',p.allocation.macro_alpha_enabled?'Enabled in saved plan':'Disabled in saved plan'],['Assumptions',human(p.allocation.assumptions_status)]].forEach(([k,v])=>{const n=el('div',undefined,'fact');n.append(el('span',k),el('strong',v));$('plan-facts').append(n);});$('limitations').replaceChildren();[...new Set([...p.limitations,...(s?.assumptions||[]),'Changing the illustrative amount scales saved paths and capital weights. It does not recalculate investor eligibility, minimum trades, nonlinear taxes or costs.','The registry is an investment menu. Availability, data qualification and mandate access are evaluated separately.','A saved release status remains attached to its original release. Viewing this dashboard does not reapprove the recommendation.'])].forEach(v=>$('limitations').append(el('li',v)));text('identifiers',`Recommendation: ${p.id}\nRelease: ${p.release_id}\nReview status: ${p.qualification.status}\nViewer version: ${data.viewer_version}`);$('identifiers').style.whiteSpace='pre-wrap';}
function selectPlan(index){state.index=index;const p=plan();state.capital=p.mandate.account_value;state.window=p.simulations?.years||p.mandate.horizon_years;state.hover=0;state.asset=null;$('asset-detail').hidden=true;$('fan-tooltip').hidden=true;$('profile').value=String(index);$('capital').value=state.capital;render();renderPortfolioIdentity(document.querySelector('[data-view].active')?.dataset.view||'overview');text('announcement',`${p.title} saved plan selected.`);}
function download(name,body,type){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(value){let v=String(value);if(/^[=+\-@\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}
