// Dated macro context and diagnostics are presentation inputs, never portfolio commands.
function analysis(){return data.context?.plans?.[plan().id]||{};}
function macro(){return $('macro-time-frame').value==='latest'&&analysis().latest_macro?analysis().latest_macro:analysis().macro||{};}
function diagnostic(){return analysis().diagnostics||{};}
function cleanLabel(value){return human(value).replace('Disinflationary Growth','Disinflationary growth').replace('Inflationary Growth','Inflationary growth').replace('Deflationary Slowdown','Deflationary slowdown');}
function score(v){return Number.isFinite(v)?v.toFixed(4):'Unavailable';}
function number(v){return Number.isFinite(v)?v.toFixed(2):'Unavailable';}
function blankChart(id,message){const c=$(id),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#647780';ctx.font='15px sans-serif';ctx.fillText(message,35,c.height/2);}
function seriesChart(id,values,labels,color='#177b68',formatter=pct,band=null){const c=$(id),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(values.length<2||values.some(v=>!Number.isFinite(v))){blankChart(id,'No sufficient dated observations available.');return;}installChartInspector(c,values,labels,formatter);const W=c.width,H=c.height,L=86,R=30,T=25,B=40;let lo=Math.min(...values),hi=Math.max(...values);if(band){lo=Math.min(lo,...band[0]);hi=Math.max(hi,...band[1]);}const spread=Math.max(hi-lo,.001);lo-=spread*.12;hi+=spread*.12;const x=i=>L+i/(values.length-1)*(W-L-R),y=v=>H-B-(v-lo)/(hi-lo)*(H-B-T);ctx.font='12px sans-serif';ctx.lineWidth=1;for(let j=0;j<5;j++){const v=lo+(hi-lo)*j/4;ctx.strokeStyle='#e8eeeb';ctx.beginPath();ctx.moveTo(L,y(v));ctx.lineTo(W-R,y(v));ctx.stroke();ctx.fillStyle='#647780';ctx.fillText(formatter(v),3,y(v)+4);}if(band){ctx.fillStyle='#dbece9';ctx.beginPath();band[0].forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));for(let i=values.length-1;i>=0;i--)ctx.lineTo(x(i),y(band[1][i]));ctx.closePath();ctx.fill();}ctx.strokeStyle=color;ctx.lineWidth=2.8;ctx.beginPath();values.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.stroke();const indices=values.length<=5?values.map((_,i)=>i):[0,Math.floor((values.length-1)/2),values.length-1];indices.forEach(i=>{ctx.fillStyle='#647780';ctx.fillText(labels[i],Math.max(L,Math.min(W-100,x(i)-20)),H-12);});c.setAttribute('aria-label',`${c.getAttribute('aria-label')?.split('. ')[0]}. ${labels[0]} ${formatter(values[0])}; ${labels.at(-1)} ${formatter(values.at(-1))}.`);}
function barsChart(id,entries,formatter=pct){const c=$(id),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);const available=entries.filter(e=>Number.isFinite(e[1]));if(!available.length){blankChart(id,'No sufficient observations for this diagnostic.');return;}const W=c.width,H=c.height,L=275,R=120,T=25,B=25,min=Math.min(0,...available.map(e=>e[1])),max=Math.max(0,...available.map(e=>e[1])),span=Math.max(max-min,.001),x=v=>L+(v-min)/span*(W-L-R),row=(H-T-B)/available.length;ctx.font='15px sans-serif';ctx.strokeStyle='#d3ddd7';ctx.beginPath();ctx.moveTo(x(0),T);ctx.lineTo(x(0),H-B);ctx.stroke();available.forEach(([label,v],i)=>{const y=T+i*row;ctx.fillStyle='#647780';ctx.fillText(label,4,y+row*.57);ctx.fillStyle=v>=0?'#177b68':'#b77c63';ctx.fillRect(Math.min(x(0),x(v)),y+row*.23,Math.max(2,Math.abs(x(v)-x(0))),row*.46);ctx.fillStyle='#1d3640';ctx.fillText(formatter(v),W-R+16,y+row*.57);});c.setAttribute('aria-label',available.map(e=>`${e[0]} ${formatter(e[1])}`).join('; '));}
