 text('performance-basis',d.label?`${d.label}. Metrics: ${d.start} to ${d.end}; charts show the latest 1,260 sessions.`:d.reason||'Observed price history was not supplied.');text('performance-assumptions',d.assumptions||'No historical account returns are being inferred.');$('performance-metrics').replaceChildren();[['Diagnostic total return','total_return'],['Annualized volatility','annualized_volatility'],['Maximum drawdown','max_drawdown'],['Daily expected shortfall · 95%','historical_daily_es95']].forEach(([label,key])=>{const card=el('div',undefined,'indicator-card');card.append(el('span',label,'small muted'),el('strong',pct(d.metrics?.[key])));$('performance-metrics').append(card);});
