 [...data.catalogue.map(i=>i.symbol),'USD_CASH'].forEach(symbol=>{const w=symbol==='USD_CASH'?r.cash:r.weights[symbol]||0,tr=el('tr'),role=r.roles[symbol]||'No role supplied',status=symbol==='USD_CASH'?'Liquidity':w>1e-8?'Allocated in this candidate':symbol==='ALLW'?'Benchmark only':'Not allocated in this fixed strategy';tr.append(el('td',symbol),el('td',`${role} ${status}.`),el('td',pct(w,2)),el('td',pct(r.risk_contributions[symbol],2)));$('lab-weights').append(tr);});
 barsChart('lab-risk-chart',Object.entries(r.risk_contributions).filter(([,v])=>Number.isFinite(v)&&Math.abs(v)>1e-6).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,12));['Equities','Nominal bonds','Inflation-linked bonds','Gold','Commodities'].forEach((name,i)=>pair($('lab-risk-budgets'),`${name} · requested / feasible sleeve risk`,`${pct(r.requested_risk_budgets?.[i])} / ${pct(r.feasible_risk_budgets?.[i])}`));
 const s=r.simulation;if(s?.status==='CONDITIONAL_RESEARCH_SCENARIOS'){[['Median horizon return',s.median_return],['5th-percentile return',s.p05_return],['95th-percentile drawdown',s.p95_max_drawdown],['Terminal loss frequency',s.terminal_loss_frequency],['Median annualized volatility',s.median_annualized_volatility],['Horizon expected shortfall · 95%',s.horizon_es95_loss]].forEach(([label,v])=>{const card=el('div',undefined,'indicator-card');card.append(el('span',label,'small muted'),el('strong',pct(v)));$('lab-simulation-metrics').append(card);});const median=[1,...s.fan[1]],lo=[1,...s.fan[0]],hi=[1,...s.fan[2]],labels=median.map((_,i)=>`${(i/63).toFixed(1)}q`);seriesChart('lab-scenario-chart',median,labels,'#177b68',v=>`${v.toFixed(2)}×`,[lo,hi]);text('lab-simulation-note',`${s.paths} conditional paths · ${s.quarters} quarters · horizon VaR 95% ${pct(s.horizon_var95_loss)} · scenario frequency of >5% drawdown ${pct(s.five_percent_drawdown_exceedance)}. These are conditional research estimates, not calibrated probabilities.`);s.assumptions.forEach(note=>$('lab-assumptions').append(el('li',note)));}else{blankChart('lab-scenario-chart','Insufficient regime-specific history.');text('lab-simulation-note',`Simulation blocked: ${human(s?.status)}. No source distribution has been invented.`);}
