function queueLabCalculation(){if(!labToken())return;++labState.request;$('lab-pdf').disabled=true;clearTimeout(labState.timer);text('lab-status','Recalculating constrained weights and conditional scenarios…');labState.timer=setTimeout(calculateLab,700);}
function parseScenarioPercentages(values){if(values.some(v=>String(v).trim()===''||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>100))throw new Error('Enter each forecast weight between 0 and 100; blank values are not zero.');const total=values.reduce((sum,v)=>sum+Number(v),0);if(total<=0)throw new Error('Forecast weights need a positive total.');return values.map(v=>Number(v)/total);}
async function calculateLab(){let normalized;try{normalized=parseScenarioPercentages(data.allocation_lab.regimes.map((_,i)=>$(`lab-prob-${i}`).value));}catch(error){text('lab-status',error.message+' Previous result remains a dated snapshot.');$('lab-pdf').disabled=true;return;}const forecast_weights=Object.fromEntries(data.allocation_lab.regimes.map((r,i)=>[r,normalized[i]]));const request=++labState.request;try{const response=await fetch('/api/reallocate',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${labToken()}`},body:JSON.stringify({strategy:labState.strategy,forecast_weights,quarters:Number($('lab-quarters').value),mode:'user_scenario'})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Calculation blocked');if(request!==labState.request)return;labState.result=result;const select=$('lab-preset');let custom=[...select.options].find(o=>o.value==='custom');if(!custom){custom=el('option','Custom supplied forecast');custom.value='custom';custom.disabled=true;select.append(custom);}select.value='custom';drawLabResult();}catch(error){if(request===labState.request)text('lab-status',`Calculation blocked: ${error.message}. Previous result remains a dated snapshot.`);}}
async function downloadLabPdf(){const token=labToken(),r=labState.result;if(!r)return;if(token){try{const response=await fetch('/api/scenario-pdf',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify({result_id:r.result_id})});if(!response.ok)throw new Error('Report unavailable; recalculate this scenario first.');const blob=await response.blob(),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='macro-driven-strategy-report.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){text('lab-status',error.message);}return;}const link=data.allocation_lab.pdf_links?.[`${labState.strategy}:${labState.preset}`];if(link){const a=el('a');a.href=link;a.download='macro-driven-strategy-report.pdf';a.click();}else window.print();}
