function drawGrowthChart(){const g=data.growth_resilience;if(!g)return;const c=$('growth-chart'),ctx=c.getContext('2d'),W=c.width,H=c.height,L=66,R=20,T=20,B=38,dd=$('growth-chart-mode').value==='drawdown';ctx.clearRect(0,0,W,H);const series=Object.entries(g.chart.series).filter(([n])=>growthVisible.has(n)).map(([n,a])=>{let peak=1;return[n,a.map(v=>{peak=Math.max(peak,v);return dd?v/peak-1:v*10000;})];});let lo=dd?0:10000,hi=dd?0:10000;series.forEach(([,a])=>a.forEach(v=>{lo=Math.min(lo,v);hi=Math.max(hi,v);}));const pad=Math.max(hi-lo,dd?.05:1000)*.12;lo-=pad;hi+=pad;const count=g.chart.dates.length,x=i=>L+i/(count-1)*(W-L-R),y=v=>H-B-(v-lo)/(hi-lo)*(H-T-B);ctx.font='12px sans-serif';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,Y=y(v);ctx.strokeStyle='#e2ebe7';ctx.beginPath();ctx.moveTo(L,Y);ctx.lineTo(W-R,Y);ctx.stroke();ctx.fillStyle='#627a7a';ctx.fillText(dd?pct(v):Math.round(v).toLocaleString(),4,Y+4);}series.forEach(([name,a])=>{ctx.strokeStyle=palette[Object.keys(g.chart.series).indexOf(name)];ctx.lineWidth=2.5;ctx.beginPath();a.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.stroke();});for(let i=0;i<=4;i++){const index=Math.round((count-1)*i/4);ctx.fillStyle='#627a7a';ctx.fillText(g.chart.dates[index].slice(0,7),Math.min(W-65,Math.max(L,x(index)-25)),H-10);}growthGeometry={L,R,W,count,series,dd};text('growth-chart-readout',dd?'Chart uses sampled closes; table max drawdowns use every daily observation.':'Hover across the chart for dated reference values. Select a legend to compare portfolios.');}
$('growth-chart').addEventListener('mousemove',event=>{if(!growthGeometry)return;const g=growthGeometry,b=event.currentTarget.getBoundingClientRect(),x=(event.clientX-b.left)/b.width*g.W,i=Math.max(0,Math.min(g.count-1,Math.round((x-g.L)/(g.W-g.L-g.R)*(g.count-1))));text('growth-chart-readout',`${data.growth_resilience.chart.dates[i]} · ${g.series.map(([n,a])=>`${n}: ${g.dd?pct(a[i]):'$'+Math.round(a[i]).toLocaleString()}`).join(' · ')}`);});
