function installChartInspector(canvas,values,labels,formatter){
 let readout=canvas.nextElementSibling;if(!readout?.classList.contains('series-readout')){readout=el('p','Hover or use arrow keys to inspect dated values.','series-readout small muted');readout.setAttribute('aria-live','polite');canvas.after(readout);}
 canvas.tabIndex=0;canvas.setAttribute('aria-describedby',canvas.id+'-readout');readout.id=canvas.id+'-readout';let selected=values.length-1;
 const inspect=i=>{selected=Math.max(0,Math.min(values.length-1,i));readout.textContent=`${labels[selected]} · ${formatter(values[selected])}`;};
 canvas.onpointermove=event=>{const rect=canvas.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width*canvas.width;inspect(Math.round((x-86)/(canvas.width-116)*(values.length-1)));};
 canvas.onkeydown=event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();inspect(event.key==='Home'?0:event.key==='End'?values.length-1:selected+(event.key==='ArrowLeft'?-1:1));}};
}

